SET NOCOUNT ON;
SET STATISTICS IO ON;
SET STATISTICS TIME ON;
 SELECT glvochcode=NULL, debit = ISNULL(SUM(S.Amt), 0), credit = 0, date = '2024-01-31', type = 'CSH-SALE', remarks='Total Invoices: ' + LTRIM(RTRIM(STR(SL.n, 7))) + ' (' + LTRIM(RTRIM(STR(SL.mn, 7))) + '-' + LTRIM(RTRIM(STR(SL.mx, 7))) + ')', acc=(SELECT name FROM accounts WHERE S.cashacccode=accounts.acccode), accounthead='Cash Sale for the Period', priority=1 FROM (SELECT h.cashacccode, amt=ISNULL(Round(SUM(d.looseqty * d.unitsalestax) + SUM(ROUND( (d.looseqty * (d.saleprice - d.itemflatdisc)) * (1 - (.01 * d.discperc)) * d.gstperc * .01, 2)) + ROUND( (SUM((d.looseqty * (d.saleprice - d.itemflatdisc)) * (1 - (.01 * d.discperc))) * (1- (.01 * h.discperc)) - h.flatdisc) * (h.invgstperc1 * .01), 2), 0) + Round( SUM((d.looseqty * (d.saleprice - d.itemflatdisc)) * (1 - (.01 * d.discperc))) * (1- (.01 * h.discperc)) + h.misccharges + h.salestax - h.flatdisc, 0), 0) FROM saleledger h, saledetail d WHERE h.saleinvcode = d.saleinvcode and h.salecatcode = 3 and h.posted = 'Y' and h.accountfor='Y' and h.date >= '2024-01-01' and h.date <= '2024-01-31' GROUP BY h.saleinvcode, h.salecatcode, h.cashacccode, h.date, h.discperc, h.misccharges, h.salestax, h.InvGSTPerc1, h.flatdisc) S LEFT JOIN (SELECT cashacccode, COUNT(*) n, MIN(SaleInvCode) mn, MAX(SaleInvCode) mx FROM saleledger WHERE salecatcode = 3 AND posted = 'Y' AND accountfor = 'Y' AND date >= '2024-01-01' AND date <= '2024-01-31' GROUP BY cashacccode) SL ON SL.cashacccode = S.cashacccode GROUP BY S.cashacccode, SL.n, SL.mn, SL.mx HAVING SUM(S.Amt) <> 0 ;
